SELECT c.comment_id, c.post_id, c.member_id, c.parent_id, c.content, c.is_deleted, c.created_at, c.updated_at, c.deleted_at, m.nickname, CASE WHEN m.profile_image IS NOT NULL THEN '/api/members/' || m.member_id || '/profile-image' ELSE NULL END as profile_image_url FROM comments c JOIN members m ON c.member_id = m.member_id WHERE c.parent_id IN
#{id}
AND c.is_deleted = 'N' ORDER BY c.created_at ASC

